import { useId } from "react";
import type { AllowanceState } from "@/lib/usage/getAllowanceState";
import styles from "./usage.module.css";
import { cn } from "@/lib/utils";

export function AllowanceGauge({
  remaining,
  total,
  state,
}: {
  remaining: number;
  total: number;
  state: AllowanceState;
}) {
  const id = useId();
  const circumference = 2 * Math.PI * 48;
  const proportion =
    total > 0 ? Math.max(0, Math.min(1, remaining / total)) : 0;
  const depleted = state === "empty" || state === "reserved";
  return (
    <div
      className="usage-ring relative w-28 h-28 flex-none"
      role="img"
      aria-label={`${remaining} of ${total} emails remaining`}
    >
      <svg
        className="-rotate-90"
        width="112"
        height="112"
        viewBox="0 0 112 112"
        aria-hidden="true"
      >
        <defs>
          <linearGradient id={id} x1="0" y1="0" x2="1" y2="1">
            <stop offset="0" stopColor="var(--usage-ring-start)" />
            <stop offset="1" stopColor="var(--usage-ring-end)" />
          </linearGradient>
        </defs>
        <circle
          cx="56"
          cy="56"
          r="48"
          fill="none"
          stroke="var(--usage-track,var(--usage-line))"
          strokeWidth="9"
        />
        {!depleted && (
          <circle
            className={styles.arc}
            cx="56"
            cy="56"
            r="48"
            fill="none"
            stroke={
              state === "low"
                ? "var(--usage-queued-color)"
                : `var(--usage-ring-paint, url(#${id}))`
            }
            strokeWidth="9"
            strokeLinecap="round"
            strokeDasharray={circumference}
            strokeDashoffset={circumference * (1 - proportion)}
          />
        )}
      </svg>
      <strong
        aria-hidden="true"
        className={cn(
          "absolute inset-0 grid place-items-center text-[34px] font-extrabold tracking-[-0.04em] workspace-mono:font-bold",
          depleted
            ? "text-[var(--usage-muted)]"
            : "workspace-mono:text-[var(--usage-number)]",
        )}
      >
        {remaining}
      </strong>
    </div>
  );
}
